import json
a=json.load(open('.ufo/evidence/round-14/dispositions-before.json',encoding='utf-8'))
b=json.load(open('.ufo/evidence/round-14/dispositions.json',encoding='utf-8'))
print('top-level keys equal:', sorted(a)==sorted(b))
for k in sorted(set(a)|set(b)):
    if k=='rows':
        continue
    print(k, 'equal' if a.get(k)==b.get(k) else 'DIFFERENT')
print('row name order equal:', [r['name'] for r in a['rows']]==[r['name'] for r in b['rows']], len(a['rows']), len(b['rows']))
ra={r['name']:r for r in a['rows']}; rb={r['name']:r for r in b['rows']}
for n in ra:
    if ra[n]!=rb.get(n):
        print('row differs:', n, 'before', ra[n].get('state'), 'after', rb[n].get('state'), 'after keys', sorted(rb[n].keys()))
print('rows identical other than differing ones:', sum(1 for n in ra if ra[n]==rb.get(n)))
